export const MODULE_FILES: Readonly<Record<string, string>> = {
  "cloudflare-access/main.tf": "# Cloudflare Access in front of the hostnames the tunnel serves:\n# - The service the deploy workflow reaches (SSH, or Portainer's webhook): a Service Auth policy\n#   that lets exactly one service token through.\n# - Portainer (opt-in): the listed email addresses, after a one-time PIN sent to that address.\n# The account's Zero Trust organization and its one-time PIN login method are shared by every\n# OpsCrew app in the account, so OpsCrew creates them outside this configuration.\nlocals {\n  service   = var.service_hostname != null\n  portainer = var.portainer_hostname != null\n}\n\nresource \"cloudflare_zero_trust_access_service_token\" \"ssh\" {\n  count      = local.service ? 1 : 0\n  account_id = var.account_id\n  name       = \"OpsCrew deploy (${var.app_name})\"\n  # Deploys must not stop working when a token expires; rotate it by re-running provision.\n  duration = \"forever\"\n}\n\nresource \"cloudflare_zero_trust_access_policy\" \"ssh\" {\n  count      = local.service ? 1 : 0\n  account_id = var.account_id\n  name       = \"OpsCrew deploy (${var.app_name})\"\n  decision   = \"non_identity\"\n  include = [\n    { service_token = { token_id = cloudflare_zero_trust_access_service_token.ssh[0].id } },\n  ]\n}\n\nresource \"cloudflare_zero_trust_access_application\" \"ssh\" {\n  count                     = local.service ? 1 : 0\n  account_id                = var.account_id\n  name                      = \"OpsCrew ${var.service_label} (${var.app_name})\"\n  type                      = \"self_hosted\"\n  domain                    = var.service_hostname\n  destinations              = [{ type = \"public\", uri = var.service_hostname }]\n  app_launcher_visible      = false\n  service_auth_401_redirect = true\n  session_duration          = \"24h\"\n  policies = [\n    { id = cloudflare_zero_trust_access_policy.ssh[0].id, precedence = 1 },\n  ]\n}\n\nresource \"cloudflare_zero_trust_access_policy\" \"portainer\" {\n  count      = local.portainer ? 1 : 0\n  account_id = var.account_id\n  name       = \"OpsCrew Portainer (${var.app_name})\"\n  decision   = \"allow\"\n  include    = [for email in var.portainer_allowed_emails : { email = { email = email } }]\n}\n\nresource \"cloudflare_zero_trust_access_application\" \"portainer\" {\n  count                     = local.portainer ? 1 : 0\n  account_id                = var.account_id\n  name                      = \"OpsCrew Portainer (${var.app_name})\"\n  type                      = \"self_hosted\"\n  domain                    = var.portainer_hostname\n  destinations              = [{ type = \"public\", uri = var.portainer_hostname }]\n  allowed_idps              = [var.one_time_pin_identity_provider_id]\n  auto_redirect_to_identity = true\n  app_launcher_visible      = false\n  session_duration          = \"24h\"\n  policies = [\n    { id = cloudflare_zero_trust_access_policy.portainer[0].id, precedence = 1 },\n  ]\n}\n",
  "cloudflare-access/outputs.tf": "output \"ssh_service_token_client_id\" {\n  description = \"Client id of the deploy workflow's service token (TUNNEL_SERVICE_TOKEN_ID); null without a service hostname.\"\n  value       = one(cloudflare_zero_trust_access_service_token.ssh[*].client_id)\n  sensitive   = true\n}\n\noutput \"ssh_service_token_client_secret\" {\n  description = \"Client secret of the deploy workflow's service token (TUNNEL_SERVICE_TOKEN_SECRET); null without a service hostname.\"\n  value       = one(cloudflare_zero_trust_access_service_token.ssh[*].client_secret)\n  sensitive   = true\n}\n",
  "cloudflare-access/variables.tf": "variable \"account_id\" {\n  description = \"Cloudflare account id (Access belongs to the account).\"\n  type        = string\n}\n\nvariable \"app_name\" {\n  description = \"App name, used in the names of the Access applications, policies and service token.\"\n  type        = string\n}\n\nvariable \"service_hostname\" {\n  description = \"Hostname of the service the deploy workflow reaches with the service token through the tunnel (SSH, or Portainer's webhook); null for none. Only the service token gets through.\"\n  type        = string\n  default     = null\n}\n\nvariable \"service_label\" {\n  description = \"What service_hostname serves, in the name of its Access application: OpsCrew <label> (<app_name>), for example SSH or Portainer webhook.\"\n  type        = string\n  default     = \"SSH\"\n}\n\nvariable \"portainer_hostname\" {\n  description = \"Hostname Portainer is served on through the tunnel; null for none. Only portainer_allowed_emails get through, after a one-time PIN.\"\n  type        = string\n  default     = null\n}\n\nvariable \"portainer_allowed_emails\" {\n  description = \"Email addresses Access lets through to Portainer.\"\n  type        = list(string)\n  default     = []\n}\n\nvariable \"one_time_pin_identity_provider_id\" {\n  description = \"Id of the account's one-time PIN login method, which Portainer's Access application uses. Required with portainer_hostname.\"\n  type        = string\n  default     = null\n}\n",
  "cloudflare-access/versions.tf": "terraform {\n  required_version = \">= 1.6.0\"\n\n  required_providers {\n    cloudflare = {\n      source  = \"cloudflare/cloudflare\"\n      version = \"~> 5.27\"\n    }\n  }\n}\n",
  "cloudflare-dns/main.tf": "resource \"cloudflare_dns_record\" \"a\" {\n  zone_id = var.zone_id\n  name    = var.domain\n  type    = \"A\"\n  content = var.ipv4\n  ttl     = 1\n  proxied = var.proxied\n  comment = \"Managed by OpsCrew\"\n}\n\nresource \"cloudflare_dns_record\" \"aaaa\" {\n  count   = var.ipv6_record ? 1 : 0\n  zone_id = var.zone_id\n  name    = var.domain\n  type    = \"AAAA\"\n  content = var.ipv6\n  ttl     = 1\n  proxied = var.proxied\n  comment = \"Managed by OpsCrew\"\n}\n\nresource \"cloudflare_dns_record\" \"www\" {\n  count   = var.www ? 1 : 0\n  zone_id = var.zone_id\n  name    = \"www.${var.domain}\"\n  type    = \"CNAME\"\n  content = var.domain\n  ttl     = 1\n  proxied = var.proxied\n  comment = \"Managed by OpsCrew\"\n}\n\n# CAA at the app's own name, naming only the authorities the server's proxy uses, and only when\n# that proxy gets the certificate (DNS only). `www` is a CNAME, so lookups follow it here. The\n# renderer passes no issuers for an app on the zone apex: CAA there would bind every name in the\n# zone.\nresource \"cloudflare_dns_record\" \"caa\" {\n  for_each = var.proxied ? toset([]) : toset(var.caa_issuers)\n  zone_id  = var.zone_id\n  name     = var.domain\n  type     = \"CAA\"\n  ttl      = 1\n  data = {\n    flags = 0\n    tag   = \"issue\"\n    value = each.value\n  }\n  comment = \"Managed by OpsCrew\"\n}\n",
  "cloudflare-dns/outputs.tf": "output \"url\" {\n  description = \"Public URL of the app.\"\n  value       = \"https://${var.domain}\"\n}\n",
  "cloudflare-dns/variables.tf": "variable \"zone_id\" {\n  description = \"Cloudflare zone id of the domain.\"\n  type        = string\n}\n\nvariable \"domain\" {\n  description = \"Hostname of the app, for example app.example.com.\"\n  type        = string\n}\n\nvariable \"ipv4\" {\n  description = \"Public IPv4 address of the server.\"\n  type        = string\n}\n\nvariable \"ipv6\" {\n  description = \"Public IPv6 address of the server; null when it has none (then set ipv6_record to false).\"\n  type        = string\n  default     = null\n}\n\nvariable \"ipv6_record\" {\n  description = \"Create the AAAA record. A separate switch because it must be known when planning, and the IPv6 address of a server created in the same plan is not.\"\n  type        = bool\n  default     = true\n}\n\nvariable \"proxied\" {\n  description = \"Send traffic through Cloudflare (hides the server IP, adds the WAF and caching).\"\n  type        = bool\n  default     = true\n}\n\nvariable \"www\" {\n  description = \"Also serve www.<domain>.\"\n  type        = bool\n  default     = false\n}\n\nvariable \"caa_issuers\" {\n  description = \"Certificate authorities named in CAA records at the domain when it is not proxied; empty for an app on the zone apex.\"\n  type        = list(string)\n  default     = []\n}\n",
  "cloudflare-dns/versions.tf": "terraform {\n  required_version = \">= 1.6.0\"\n\n  required_providers {\n    cloudflare = {\n      source  = \"cloudflare/cloudflare\"\n      version = \"~> 5.27\"\n    }\n  }\n}\n",
  "cloudflare-tunnel/main.tf": "# A remotely managed Cloudflare Tunnel: its routes live in Cloudflare (config_src = \"cloudflare\"),\n# and the connector on the server only needs the tunnel token (output \"token\").\nresource \"cloudflare_zero_trust_tunnel_cloudflared\" \"this\" {\n  account_id = var.account_id\n  name       = var.name\n  config_src = \"cloudflare\"\n}\n\nresource \"cloudflare_zero_trust_tunnel_cloudflared_config\" \"this\" {\n  account_id = var.account_id\n  tunnel_id  = cloudflare_zero_trust_tunnel_cloudflared.this.id\n\n  config = {\n    # Every route in order, then a final rule that answers 404 for any other hostname (and for\n    # the paths a route with a path does not match).\n    ingress = concat(\n      [\n        for route in var.routes : {\n          hostname       = route.hostname\n          path           = route.path\n          service        = route.service\n          origin_request = route.no_tls_verify ? { no_tls_verify = true } : null\n        }\n      ],\n      [\n        {\n          hostname       = null\n          path           = null\n          service        = \"http_status:404\"\n          origin_request = null\n        },\n      ],\n    )\n  }\n}\n\nresource \"cloudflare_dns_record\" \"route\" {\n  for_each = toset([for route in var.routes : route.hostname])\n\n  zone_id = var.zone_id\n  name    = each.value\n  type    = \"CNAME\"\n  content = \"${cloudflare_zero_trust_tunnel_cloudflared.this.id}.cfargotunnel.com\"\n  ttl     = 1\n  proxied = true\n  comment = \"Managed by OpsCrew\"\n}\n\ndata \"cloudflare_zero_trust_tunnel_cloudflared_token\" \"this\" {\n  account_id = var.account_id\n  tunnel_id  = cloudflare_zero_trust_tunnel_cloudflared.this.id\n}\n",
  "cloudflare-tunnel/outputs.tf": "output \"tunnel_id\" {\n  description = \"UUID of the tunnel.\"\n  value       = cloudflare_zero_trust_tunnel_cloudflared.this.id\n}\n\noutput \"token\" {\n  description = \"Token the connector on the server runs the tunnel with. Secret: it goes only into a root-only file on the server.\"\n  value       = data.cloudflare_zero_trust_tunnel_cloudflared_token.this.token\n  sensitive   = true\n}\n",
  "cloudflare-tunnel/variables.tf": "variable \"account_id\" {\n  description = \"Cloudflare account id (tunnels belong to the account).\"\n  type        = string\n}\n\nvariable \"zone_id\" {\n  description = \"Cloudflare zone id of the hostnames the tunnel serves.\"\n  type        = string\n}\n\nvariable \"name\" {\n  description = \"Name of the tunnel, for example opscrew-shop.\"\n  type        = string\n}\n\nvariable \"routes\" {\n  description = \"Public hostnames the tunnel serves and the service on the server each one reaches, for example http://localhost:18080 or ssh://localhost:22. A route with a path (a regular expression, for example ^/api/) serves only the request paths it matches. Requests for any other hostname or path get a 404.\"\n  type = list(object({\n    hostname      = string\n    path          = optional(string)\n    service       = string\n    no_tls_verify = optional(bool, false)\n  }))\n}\n",
  "cloudflare-tunnel/versions.tf": "terraform {\n  required_version = \">= 1.6.0\"\n\n  required_providers {\n    cloudflare = {\n      source  = \"cloudflare/cloudflare\"\n      version = \"~> 5.27\"\n    }\n  }\n}\n",
  "digitalocean-droplet/cloud-init.yaml.tftpl": "#cloud-config\n# Rendered by OpsCrew. Runs once at first boot: creates the deploy user, hardens SSH, installs\n# Docker Engine (28 or newer, from Docker's apt repository), fail2ban, automatic security updates\n# and the host firewall, and prepares what a GitHub Actions runner needs from root (so one can be\n# added later as deploy, which has no root). /var/lib/opscrew-ready is written only when Docker\n# installed correctly.\nusers:\n  - name: deploy\n    shell: /bin/bash\n    lock_passwd: true\n    ssh_authorized_keys:\n      - ${ssh_public_key}\nssh_pwauth: false\ndisable_root: true\npackage_update: true\npackage_upgrade: true\npackages:\n  - ca-certificates\n  - fail2ban\n  - unattended-upgrades\n  - ufw\n  - curl\n  # The GitHub Actions runner's system libraries, as its bin/installdependencies.sh (v2.338.0)\n  # picks them on Ubuntu 24.04.\n  - libicu74\n  - libkrb5-3\n  - liblttng-ust1t64\n  - libssl3t64\n  - zlib1g\nwrite_files:\n  - path: /etc/ssh/sshd_config.d/10-opscrew.conf\n    permissions: \"0644\"\n    content: |\n      PasswordAuthentication no\n      KbdInteractiveAuthentication no\n      PermitRootLogin no\n      MaxAuthTries 3\n      X11Forwarding no\n      AllowUsers deploy\n      KexAlgorithms sntrup761x25519-sha512@openssh.com,curve25519-sha256,curve25519-sha256@libssh.org,diffie-hellman-group18-sha512,diffie-hellman-group-exchange-sha256,diffie-hellman-group16-sha512\n      Ciphers chacha20-poly1305@openssh.com,aes256-gcm@openssh.com,aes256-ctr,aes192-ctr,aes128-gcm@openssh.com,aes128-ctr\n      MACs hmac-sha2-512-etm@openssh.com,hmac-sha2-256-etm@openssh.com,umac-128-etm@openssh.com\n      RequiredRSASize 3072\n      HostKey /etc/ssh/ssh_host_ed25519_key\n      HostKey /etc/ssh/ssh_host_rsa_key\n      HostKeyAlgorithms sk-ssh-ed25519-cert-v01@openssh.com,ssh-ed25519-cert-v01@openssh.com,rsa-sha2-512-cert-v01@openssh.com,rsa-sha2-256-cert-v01@openssh.com,sk-ssh-ed25519@openssh.com,ssh-ed25519,rsa-sha2-512,rsa-sha2-256\n      CASignatureAlgorithms sk-ssh-ed25519@openssh.com,ssh-ed25519,rsa-sha2-512,rsa-sha2-256\n      HostbasedAcceptedAlgorithms sk-ssh-ed25519-cert-v01@openssh.com,ssh-ed25519-cert-v01@openssh.com,sk-ssh-ed25519@openssh.com,ssh-ed25519,rsa-sha2-512-cert-v01@openssh.com,rsa-sha2-512,rsa-sha2-256-cert-v01@openssh.com,rsa-sha2-256\n      PubkeyAcceptedAlgorithms sk-ssh-ed25519-cert-v01@openssh.com,ssh-ed25519-cert-v01@openssh.com,rsa-sha2-512-cert-v01@openssh.com,rsa-sha2-256-cert-v01@openssh.com,sk-ssh-ed25519@openssh.com,ssh-ed25519,rsa-sha2-512,rsa-sha2-256\n      ModuliFile /etc/ssh/moduli.opscrew\n  - path: /etc/fail2ban/jail.d/opscrew.local\n    permissions: \"0644\"\n    content: |\n      [sshd]\n      enabled = true\n      maxretry = 5\n      bantime = 1h\n  - path: /etc/docker/daemon.json\n    permissions: \"0644\"\n    content: |\n      {\n        \"log-driver\": \"json-file\",\n        \"log-opts\": { \"max-size\": \"10m\", \"max-file\": \"3\" },\n        \"no-new-privileges\": true,\n        \"live-restore\": true\n      }\n  - path: /usr/local/sbin/opscrew-install-docker\n    permissions: \"0755\"\n    content: |\n      #!/bin/sh\n      set -eu\n      # Installs Docker Engine and its Buildx and Compose plugins from Docker's apt repository\n      # (https://docs.docker.com/engine/install/ubuntu/). With --check, only verifies the install.\n      fail() {\n        echo \"opscrew: $*\" >&2\n        exit 1\n      }\n      check() {\n        version=\"$(docker version --format \"{{.Server.Version}}\")\" || fail \"Docker Engine is not running\"\n        major=\"$${version%%.*}\"\n        case \"$major\" in\n          '' | *[!0-9]*) fail \"unexpected Docker Engine version '$version'\" ;;\n        esac\n        if [ \"$major\" -lt 28 ]; then\n          fail \"Docker Engine $version is older than 28\"\n        fi\n        docker compose version >/dev/null || fail \"the Docker Compose plugin is missing\"\n        docker buildx version >/dev/null || fail \"the Docker Buildx plugin is missing\"\n      }\n      if [ \"$${1:-}\" = \"--check\" ]; then\n        check\n        exit 0\n      fi\n      . /etc/os-release\n      [ \"$${ID:-}\" = ubuntu ] || fail \"expected Ubuntu, found $${ID:-an unknown system}\"\n      codename=\"$${UBUNTU_CODENAME:-$${VERSION_CODENAME:-}}\"\n      [ -n \"$codename\" ] || fail \"cannot tell the Ubuntu release from /etc/os-release\"\n      arch=\"$(dpkg --print-architecture)\"\n      install -m 0755 -d /etc/apt/keyrings\n      curl -fsSL --retry 5 https://download.docker.com/linux/ubuntu/gpg -o /etc/apt/keyrings/docker.asc\n      chmod a+r /etc/apt/keyrings/docker.asc\n      cat > /etc/apt/sources.list.d/docker.sources <<EOF\n      Types: deb\n      URIs: https://download.docker.com/linux/ubuntu\n      Suites: $codename\n      Components: stable\n      Architectures: $arch\n      Signed-By: /etc/apt/keyrings/docker.asc\n      EOF\n      export DEBIAN_FRONTEND=noninteractive\n      apt-get -o DPkg::Lock::Timeout=600 update\n      apt-get -o DPkg::Lock::Timeout=600 install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin\n      systemctl enable --now docker\n      check\n  - path: /etc/apt/apt.conf.d/20auto-upgrades\n    permissions: \"0644\"\n    content: |\n      APT::Periodic::Update-Package-Lists \"1\";\n      APT::Periodic::Unattended-Upgrade \"1\";\nruncmd:\n  - [/usr/local/sbin/opscrew-install-docker]\n  - [usermod, -aG, docker, deploy]\n  # deploy's services (a GitHub Actions runner) run without a login, from boot on.\n  - [loginctl, enable-linger, deploy]\n  # The shared edge, the apps' folders and their data, as on servers the user owns, and the\n  # runners' parent; the first deploy brings up the edge.\n  - [install, -d, -m, \"0750\", -o, deploy, -g, deploy, /srv/edge, /srv/apps, /srv/data, /srv/runners]\n  - [ufw, default, deny, incoming]\n  - [ufw, allow, 22/tcp]\n  - [ufw, allow, 80/tcp]\n  - [ufw, allow, 443/tcp]\n  - [ufw, allow, 443/udp]\n  - [ufw, --force, enable]\n  - [systemctl, enable, --now, docker, fail2ban, unattended-upgrades]\n  # SSH: a copy of the moduli with only the groups of 3072 bits and more (ModuliFile; the conffile\n  # /etc/ssh/moduli is never changed), and the hardened settings only when\n  # sshd -t accepts them; otherwise the stock settings stay, and the server is never marked ready.\n  - [sh, -c, \"awk '$5 >= 3071' /etc/ssh/moduli > /etc/ssh/moduli.opscrew\"]\n  - [sh, -c, \"install -d -m 0755 /run/sshd && sshd -t || rm -f /etc/ssh/sshd_config.d/10-opscrew.conf\"]\n  - [systemctl, restart, ssh]\n  - [sh, -c, \"/usr/local/sbin/opscrew-install-docker --check && test -f /etc/ssh/sshd_config.d/10-opscrew.conf && touch /var/lib/opscrew-ready\"]\n",
  "digitalocean-droplet/main.tf": "# Only the app's own tag is managed here. Deleting a DigitalOcean tag removes it from every\n# resource in the account, so shared tags (managed-by:opscrew) are never resources: the Droplet\n# create call adds them by name and creates them when missing.\nresource \"digitalocean_tag\" \"app\" {\n  name = var.app_tag\n}\n\nresource \"digitalocean_ssh_key\" \"deploy\" {\n  name       = \"${var.name}-deploy\"\n  public_key = var.ssh_public_key\n}\n\nresource \"digitalocean_droplet\" \"this\" {\n  name       = var.name\n  region     = var.region\n  size       = var.size\n  image      = var.image\n  backups    = var.backups\n  ipv6       = true\n  monitoring = true\n  ssh_keys   = [digitalocean_ssh_key.deploy.fingerprint]\n  tags       = concat([digitalocean_tag.app.name], var.shared_tags)\n\n  user_data = templatefile(\"${path.module}/cloud-init.yaml.tftpl\", {\n    ssh_public_key = var.ssh_public_key\n  })\n\n  # Daily backups at 04:00 UTC; the block is left out when backups are off.\n  dynamic \"backup_policy\" {\n    for_each = var.backups ? [1] : []\n    content {\n      plan = \"daily\"\n      hour = 4\n    }\n  }\n\n  lifecycle {\n    # Changing these would rebuild the Droplet and lose its data; OpsCrew never does that silently.\n    ignore_changes = [user_data, image, ssh_keys]\n  }\n}\n\n# DigitalOcean firewalls block everything that is not allowed, outbound included, so outbound\n# traffic is allowed explicitly.\nresource \"digitalocean_firewall\" \"this\" {\n  name        = \"${var.name}-firewall\"\n  droplet_ids = [digitalocean_droplet.this.id]\n\n  inbound_rule {\n    protocol         = \"tcp\"\n    port_range       = \"22\"\n    source_addresses = var.ssh_allowed_cidrs\n  }\n\n  inbound_rule {\n    protocol         = \"tcp\"\n    port_range       = \"80\"\n    source_addresses = var.http_allowed_cidrs\n  }\n\n  inbound_rule {\n    protocol         = \"tcp\"\n    port_range       = \"443\"\n    source_addresses = var.http_allowed_cidrs\n  }\n\n  inbound_rule {\n    protocol         = \"udp\"\n    port_range       = \"443\"\n    source_addresses = var.http_allowed_cidrs\n  }\n\n  inbound_rule {\n    protocol         = \"icmp\"\n    source_addresses = [\"0.0.0.0/0\", \"::/0\"]\n  }\n\n  outbound_rule {\n    protocol              = \"tcp\"\n    port_range            = \"1-65535\"\n    destination_addresses = [\"0.0.0.0/0\", \"::/0\"]\n  }\n\n  outbound_rule {\n    protocol              = \"udp\"\n    port_range            = \"1-65535\"\n    destination_addresses = [\"0.0.0.0/0\", \"::/0\"]\n  }\n\n  outbound_rule {\n    protocol              = \"icmp\"\n    destination_addresses = [\"0.0.0.0/0\", \"::/0\"]\n  }\n}\n",
  "digitalocean-droplet/outputs.tf": "output \"ipv4_address\" {\n  description = \"Public IPv4 address of the Droplet.\"\n  value       = digitalocean_droplet.this.ipv4_address\n}\n\noutput \"ipv6_address\" {\n  description = \"Public IPv6 address of the Droplet.\"\n  value       = digitalocean_droplet.this.ipv6_address\n}\n\noutput \"server_id\" {\n  description = \"DigitalOcean Droplet id, as a string.\"\n  value       = tostring(digitalocean_droplet.this.id)\n}\n\noutput \"server_name\" {\n  description = \"Droplet name.\"\n  value       = digitalocean_droplet.this.name\n}\n",
  "digitalocean-droplet/variables.tf": "variable \"name\" {\n  description = \"Droplet name; also prefixes the firewall and SSH key names.\"\n  type        = string\n}\n\nvariable \"region\" {\n  description = \"DigitalOcean region, for example fra1.\"\n  type        = string\n}\n\nvariable \"size\" {\n  description = \"DigitalOcean Droplet size, for example s-1vcpu-2gb.\"\n  type        = string\n}\n\nvariable \"image\" {\n  description = \"Operating system image.\"\n  type        = string\n  default     = \"ubuntu-24-04-x64\"\n}\n\nvariable \"backups\" {\n  description = \"Enable DigitalOcean daily backups (they cost extra; `opscrew design` shows the price; kept up to four weeks after the Droplet is deleted).\"\n  type        = bool\n  default     = false\n}\n\nvariable \"ssh_public_key\" {\n  description = \"Public half of the OpsCrew deploy key (ssh-ed25519 ...).\"\n  type        = string\n}\n\nvariable \"ssh_allowed_cidrs\" {\n  description = \"Networks allowed to reach SSH (port 22).\"\n  type        = list(string)\n  default     = [\"0.0.0.0/0\", \"::/0\"]\n}\n\nvariable \"http_allowed_cidrs\" {\n  description = \"Networks allowed to reach HTTP/HTTPS (ports 80 and 443).\"\n  type        = list(string)\n  default     = [\"0.0.0.0/0\", \"::/0\"]\n}\n\nvariable \"app_tag\" {\n  description = \"The app's own tag, for example opscrew-app:shop; created with the Droplet and deleted with it.\"\n  type        = string\n}\n\nvariable \"shared_tags\" {\n  description = \"Tags shared with other apps, for example managed-by:opscrew; added to the Droplet by name and never deleted.\"\n  type        = list(string)\n  default     = []\n}\n",
  "digitalocean-droplet/versions.tf": "terraform {\n  required_version = \">= 1.6.0\"\n\n  required_providers {\n    digitalocean = {\n      source  = \"digitalocean/digitalocean\"\n      version = \"~> 2.106\"\n    }\n  }\n}\n",
  "hetzner-vps/cloud-init.yaml.tftpl": "#cloud-config\n# Rendered by OpsCrew. Runs once at first boot: creates the deploy user, hardens SSH, installs\n# Docker Engine (28 or newer, from Docker's apt repository), fail2ban, automatic security updates\n# and the host firewall, and prepares what a GitHub Actions runner needs from root (so one can be\n# added later as deploy, which has no root). /var/lib/opscrew-ready is written only when Docker\n# installed correctly.\nusers:\n  - name: deploy\n    shell: /bin/bash\n    lock_passwd: true\n    ssh_authorized_keys:\n      - ${ssh_public_key}\nssh_pwauth: false\ndisable_root: true\npackage_update: true\npackage_upgrade: true\npackages:\n  - ca-certificates\n  - fail2ban\n  - unattended-upgrades\n  - ufw\n  - curl\n  # The GitHub Actions runner's system libraries, as its bin/installdependencies.sh (v2.338.0)\n  # picks them on Ubuntu 24.04.\n  - libicu74\n  - libkrb5-3\n  - liblttng-ust1t64\n  - libssl3t64\n  - zlib1g\nwrite_files:\n  - path: /etc/ssh/sshd_config.d/10-opscrew.conf\n    permissions: \"0644\"\n    content: |\n      PasswordAuthentication no\n      KbdInteractiveAuthentication no\n      PermitRootLogin no\n      MaxAuthTries 3\n      X11Forwarding no\n      AllowUsers deploy\n      KexAlgorithms sntrup761x25519-sha512@openssh.com,curve25519-sha256,curve25519-sha256@libssh.org,diffie-hellman-group18-sha512,diffie-hellman-group-exchange-sha256,diffie-hellman-group16-sha512\n      Ciphers chacha20-poly1305@openssh.com,aes256-gcm@openssh.com,aes256-ctr,aes192-ctr,aes128-gcm@openssh.com,aes128-ctr\n      MACs hmac-sha2-512-etm@openssh.com,hmac-sha2-256-etm@openssh.com,umac-128-etm@openssh.com\n      RequiredRSASize 3072\n      HostKey /etc/ssh/ssh_host_ed25519_key\n      HostKey /etc/ssh/ssh_host_rsa_key\n      HostKeyAlgorithms sk-ssh-ed25519-cert-v01@openssh.com,ssh-ed25519-cert-v01@openssh.com,rsa-sha2-512-cert-v01@openssh.com,rsa-sha2-256-cert-v01@openssh.com,sk-ssh-ed25519@openssh.com,ssh-ed25519,rsa-sha2-512,rsa-sha2-256\n      CASignatureAlgorithms sk-ssh-ed25519@openssh.com,ssh-ed25519,rsa-sha2-512,rsa-sha2-256\n      HostbasedAcceptedAlgorithms sk-ssh-ed25519-cert-v01@openssh.com,ssh-ed25519-cert-v01@openssh.com,sk-ssh-ed25519@openssh.com,ssh-ed25519,rsa-sha2-512-cert-v01@openssh.com,rsa-sha2-512,rsa-sha2-256-cert-v01@openssh.com,rsa-sha2-256\n      PubkeyAcceptedAlgorithms sk-ssh-ed25519-cert-v01@openssh.com,ssh-ed25519-cert-v01@openssh.com,rsa-sha2-512-cert-v01@openssh.com,rsa-sha2-256-cert-v01@openssh.com,sk-ssh-ed25519@openssh.com,ssh-ed25519,rsa-sha2-512,rsa-sha2-256\n      ModuliFile /etc/ssh/moduli.opscrew\n  - path: /etc/fail2ban/jail.d/opscrew.local\n    permissions: \"0644\"\n    content: |\n      [sshd]\n      enabled = true\n      maxretry = 5\n      bantime = 1h\n  - path: /etc/docker/daemon.json\n    permissions: \"0644\"\n    content: |\n      {\n        \"log-driver\": \"json-file\",\n        \"log-opts\": { \"max-size\": \"10m\", \"max-file\": \"3\" },\n        \"no-new-privileges\": true,\n        \"live-restore\": true\n      }\n  - path: /usr/local/sbin/opscrew-install-docker\n    permissions: \"0755\"\n    content: |\n      #!/bin/sh\n      set -eu\n      # Installs Docker Engine and its Buildx and Compose plugins from Docker's apt repository\n      # (https://docs.docker.com/engine/install/ubuntu/). With --check, only verifies the install.\n      fail() {\n        echo \"opscrew: $*\" >&2\n        exit 1\n      }\n      check() {\n        version=\"$(docker version --format \"{{.Server.Version}}\")\" || fail \"Docker Engine is not running\"\n        major=\"$${version%%.*}\"\n        case \"$major\" in\n          '' | *[!0-9]*) fail \"unexpected Docker Engine version '$version'\" ;;\n        esac\n        if [ \"$major\" -lt 28 ]; then\n          fail \"Docker Engine $version is older than 28\"\n        fi\n        docker compose version >/dev/null || fail \"the Docker Compose plugin is missing\"\n        docker buildx version >/dev/null || fail \"the Docker Buildx plugin is missing\"\n      }\n      if [ \"$${1:-}\" = \"--check\" ]; then\n        check\n        exit 0\n      fi\n      . /etc/os-release\n      [ \"$${ID:-}\" = ubuntu ] || fail \"expected Ubuntu, found $${ID:-an unknown system}\"\n      codename=\"$${UBUNTU_CODENAME:-$${VERSION_CODENAME:-}}\"\n      [ -n \"$codename\" ] || fail \"cannot tell the Ubuntu release from /etc/os-release\"\n      arch=\"$(dpkg --print-architecture)\"\n      install -m 0755 -d /etc/apt/keyrings\n      curl -fsSL --retry 5 https://download.docker.com/linux/ubuntu/gpg -o /etc/apt/keyrings/docker.asc\n      chmod a+r /etc/apt/keyrings/docker.asc\n      cat > /etc/apt/sources.list.d/docker.sources <<EOF\n      Types: deb\n      URIs: https://download.docker.com/linux/ubuntu\n      Suites: $codename\n      Components: stable\n      Architectures: $arch\n      Signed-By: /etc/apt/keyrings/docker.asc\n      EOF\n      export DEBIAN_FRONTEND=noninteractive\n      apt-get -o DPkg::Lock::Timeout=600 update\n      apt-get -o DPkg::Lock::Timeout=600 install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin\n      systemctl enable --now docker\n      check\n  - path: /etc/apt/apt.conf.d/20auto-upgrades\n    permissions: \"0644\"\n    content: |\n      APT::Periodic::Update-Package-Lists \"1\";\n      APT::Periodic::Unattended-Upgrade \"1\";\nruncmd:\n  - [/usr/local/sbin/opscrew-install-docker]\n  - [usermod, -aG, docker, deploy]\n  # deploy's services (a GitHub Actions runner) run without a login, from boot on.\n  - [loginctl, enable-linger, deploy]\n  # The shared edge, the apps' folders and their data, as on servers the user owns, and the\n  # runners' parent; the first deploy brings up the edge.\n  - [install, -d, -m, \"0750\", -o, deploy, -g, deploy, /srv/edge, /srv/apps, /srv/data, /srv/runners]\n  - [ufw, default, deny, incoming]\n  - [ufw, allow, 22/tcp]\n  - [ufw, allow, 80/tcp]\n  - [ufw, allow, 443/tcp]\n  - [ufw, allow, 443/udp]\n  - [ufw, --force, enable]\n  - [systemctl, enable, --now, docker, fail2ban, unattended-upgrades]\n  # SSH: a copy of the moduli with only the groups of 3072 bits and more (ModuliFile; the conffile\n  # /etc/ssh/moduli is never changed), and the hardened settings only when\n  # sshd -t accepts them; otherwise the stock settings stay, and the server is never marked ready.\n  - [sh, -c, \"awk '$5 >= 3071' /etc/ssh/moduli > /etc/ssh/moduli.opscrew\"]\n  - [sh, -c, \"install -d -m 0755 /run/sshd && sshd -t || rm -f /etc/ssh/sshd_config.d/10-opscrew.conf\"]\n  - [systemctl, restart, ssh]\n  - [sh, -c, \"/usr/local/sbin/opscrew-install-docker --check && test -f /etc/ssh/sshd_config.d/10-opscrew.conf && touch /var/lib/opscrew-ready\"]\n",
  "hetzner-vps/main.tf": "resource \"hcloud_ssh_key\" \"deploy\" {\n  name       = \"${var.name}-deploy\"\n  public_key = var.ssh_public_key\n  labels     = var.labels\n}\n\nresource \"hcloud_firewall\" \"this\" {\n  name   = \"${var.name}-firewall\"\n  labels = var.labels\n\n  rule {\n    description = \"SSH\"\n    direction   = \"in\"\n    protocol    = \"tcp\"\n    port        = \"22\"\n    source_ips  = var.ssh_allowed_cidrs\n  }\n\n  rule {\n    description = \"HTTP\"\n    direction   = \"in\"\n    protocol    = \"tcp\"\n    port        = \"80\"\n    source_ips  = var.http_allowed_cidrs\n  }\n\n  rule {\n    description = \"HTTPS\"\n    direction   = \"in\"\n    protocol    = \"tcp\"\n    port        = \"443\"\n    source_ips  = var.http_allowed_cidrs\n  }\n\n  rule {\n    description = \"HTTP/3\"\n    direction   = \"in\"\n    protocol    = \"udp\"\n    port        = \"443\"\n    source_ips  = var.http_allowed_cidrs\n  }\n\n  rule {\n    description = \"Ping\"\n    direction   = \"in\"\n    protocol    = \"icmp\"\n    source_ips  = [\"0.0.0.0/0\", \"::/0\"]\n  }\n\n  lifecycle {\n    # The server attaches this firewall (firewall_ids, so it is protected from its first boot);\n    # Hetzner mirrors that attachment into apply_to, which is not set here. Ignoring it keeps\n    # `opscrew drift` from reporting a change nobody made; a detached firewall still shows up as\n    # drift on the server's firewall_ids.\n    ignore_changes = [apply_to]\n  }\n}\n\nresource \"hcloud_server\" \"this\" {\n  name               = var.name\n  server_type        = var.server_type\n  location           = var.location\n  image              = var.image\n  backups            = var.backups\n  ssh_keys           = [hcloud_ssh_key.deploy.id]\n  firewall_ids       = [hcloud_firewall.this.id]\n  delete_protection  = var.delete_protection\n  rebuild_protection = var.delete_protection\n  labels             = var.labels\n\n  user_data = templatefile(\"${path.module}/cloud-init.yaml.tftpl\", {\n    ssh_public_key = var.ssh_public_key\n  })\n\n  public_net {\n    ipv4_enabled = true\n    ipv6_enabled = true\n  }\n\n  lifecycle {\n    # Changing these would rebuild the server and lose its data; OpsCrew never does that silently.\n    ignore_changes = [user_data, image, ssh_keys]\n  }\n}\n",
  "hetzner-vps/outputs.tf": "output \"ipv4_address\" {\n  description = \"Public IPv4 address of the server.\"\n  value       = hcloud_server.this.ipv4_address\n}\n\noutput \"ipv6_address\" {\n  description = \"Public IPv6 address of the server.\"\n  value       = hcloud_server.this.ipv6_address\n}\n\noutput \"server_id\" {\n  description = \"Hetzner Cloud server id.\"\n  value       = hcloud_server.this.id\n}\n\noutput \"server_name\" {\n  description = \"Server name.\"\n  value       = hcloud_server.this.name\n}\n",
  "hetzner-vps/variables.tf": "variable \"name\" {\n  description = \"Server name; also prefixes the firewall and SSH key names.\"\n  type        = string\n}\n\nvariable \"location\" {\n  description = \"Hetzner Cloud location, for example nbg1.\"\n  type        = string\n}\n\nvariable \"server_type\" {\n  description = \"Hetzner Cloud server type, for example cx23.\"\n  type        = string\n}\n\nvariable \"image\" {\n  description = \"Operating system image.\"\n  type        = string\n  default     = \"ubuntu-24.04\"\n}\n\nvariable \"backups\" {\n  description = \"Enable Hetzner automated backups (they cost extra; `opscrew design` shows the price).\"\n  type        = bool\n  default     = false\n}\n\nvariable \"ssh_public_key\" {\n  description = \"Public half of the OpsCrew deploy key (ssh-ed25519 ...).\"\n  type        = string\n}\n\nvariable \"ssh_allowed_cidrs\" {\n  description = \"Networks allowed to reach SSH (port 22).\"\n  type        = list(string)\n  default     = [\"0.0.0.0/0\", \"::/0\"]\n}\n\nvariable \"http_allowed_cidrs\" {\n  description = \"Networks allowed to reach HTTP/HTTPS (ports 80 and 443).\"\n  type        = list(string)\n  default     = [\"0.0.0.0/0\", \"::/0\"]\n}\n\nvariable \"delete_protection\" {\n  description = \"Protect the server against accidental deletion and rebuilds.\"\n  type        = bool\n  default     = true\n}\n\nvariable \"labels\" {\n  description = \"Labels added to every resource.\"\n  type        = map(string)\n  default     = {}\n}\n",
  "hetzner-vps/versions.tf": "terraform {\n  required_version = \">= 1.6.0\"\n\n  required_providers {\n    hcloud = {\n      source  = \"hetznercloud/hcloud\"\n      version = \"~> 1.70\"\n    }\n  }\n}\n",
};
